//! The golden corpus, replayed against the Rust port.
//!
//! This turns "was it ported correctly?" from a reading exercise into a
//! failing test. The files under `fixtures/state/` are generated by the
//! fixture generator (not included) from cases lifted out of the Python
//! reference implementation's test suite; the reference re-asserts that it
//! still produces them, and this file asserts that the Rust does too. Neither
//! implementation can move without the other failing.
//!
//! Every case here is a Python behaviour, including the ones that are arguably
//! wrong ("A edit." rather than "An edit."). The plan names this explicitly as
//! risk 4: a fixture pins CURRENT behaviour and is not a judgement about
//! whether the behaviour is right. Disagreements are reported, not silently
//! corrected.

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;

use heard_state::agent_state::{
    approx_tokens, compute_response_shape_hint, compute_salience_hint, tool_name_from_tag,
    AgentSnapshot, AgentState, AgentStateRegistry, NoLabel,
};
use heard_state::clock::ManualClock;
use heard_state::event::AgentEvent;
use heard_state::history::History;
use heard_state::multi_agent::{
    auto_voice_for, format_project_summary, DigestEvent, MultiAgentRouter, ProjectRootFinder,
};
use heard_state::project_name::{BasenameProjectNamer, GitProjectNamer};
use heard_state::pyjson::{record_from_fixture, PyValue};
use heard_state::session::SessionStore;
use heard_state::spoken::SpokenStore;
use serde_json::Value;

fn fixture(name: &str) -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/state")
        .join(name);
    let text = fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{} — run `python3 -m tools.fixtures_state` from engine/: {e}",
            path.display()
        )
    });
    serde_json::from_str(&text)
        .unwrap_or_else(|e| panic!("{} is not valid JSON: {e}", path.display()))
}

fn scratch(tag: &str) -> PathBuf {
    static COUNTER: AtomicU32 = AtomicU32::new(0);
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    let dir = std::env::temp_dir().join(format!(
        "heard-state-fixtures-{tag}-{}-{n}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("scratch dir");
    dir
}

fn as_str(value: &Value) -> &str {
    value.as_str().unwrap_or_default()
}

fn opt_string(value: &Value) -> Option<String> {
    value.as_str().map(str::to_string)
}

