#[test]
fn agent_state_helper_tables_match() {
    let data = fixture("agent_state.json");

    for case in data["tool_name_from_tag"].as_array().expect("array") {
        let tag = as_str(&case["tag"]);
        assert_eq!(
            tool_name_from_tag(tag),
            opt_string(&case["expect"]),
            "tool_name_from_tag({tag:?})"
        );
    }

    for case in data["approx_tokens"].as_array().expect("array") {
        let chars = case["chars"].as_u64().expect("chars") as usize;
        let text = "x".repeat(chars);
        assert_eq!(
            approx_tokens(&text) as u64,
            case["expect"].as_u64().expect("expect"),
            "approx_tokens over {chars} chars"
        );
    }

    for case in data["response_shape_hint"].as_array().expect("array") {
        let window: std::collections::VecDeque<usize> = case["window"]
            .as_array()
            .expect("window")
            .iter()
            .map(|v| v.as_u64().expect("token count") as usize)
            .collect();
        assert_eq!(
            compute_response_shape_hint(&window).as_str(),
            as_str(&case["expect"]),
            "response shape over {window:?}"
        );
    }

    for case in data["salience_hint"].as_array().expect("array") {
        let mut state = AgentState::new("probe", 0.0, 0.0);
        state.error_count = case["error_count"].as_u64().expect("error_count");
        state.event_count = case["event_count"].as_u64().expect("event_count");
        state.current_tool = opt_string(&case["current_tool"]);
        state.recent_output_tokens = case["window"]
            .as_array()
            .expect("window")
            .iter()
            .map(|v| v.as_u64().expect("token count") as usize)
            .collect();
        state.last_event_at = 0.0;
        let now = case["idle_seconds"].as_f64().expect("idle_seconds");
        assert_eq!(
            compute_salience_hint(&state, now).as_str(),
            as_str(&case["expect"]),
            "salience for {case}"
        );
    }
}

#[test]
fn agent_state_sequences_match() {
    let data = fixture("agent_state.json");
    for case in data["sequences"].as_array().expect("array") {
        let name = as_str(&case["name"]);
        // A ManualClock keeps `last_tool_duration_s` and the idle window
        // reproducible; the snapshot only records presence, but the salience
        // hint reads the idle window, so the clock has to be still.
        let clock = Arc::new(ManualClock::new(1_000_000.0));
        let registry =
            AgentStateRegistry::with(clock, Arc::new(BasenameProjectNamer), Arc::new(NoLabel));
        for raw in case["events"].as_array().expect("events") {
            let event: AgentEvent =
                serde_json::from_value(raw.clone()).unwrap_or_else(|e| panic!("{name}: {e}"));
            registry.observe(&event);
        }
        let expected: HashMap<String, AgentSnapshot> =
            serde_json::from_value(case["expect"].clone())
                .unwrap_or_else(|e| panic!("{name}: expectation does not parse: {e}"));
        let actual: HashMap<String, AgentSnapshot> = registry
            .all()
            .iter()
            .map(|a| (a.id.clone(), a.snapshot()))
            .collect();
        assert_eq!(actual, expected, "agent_state sequence {name}");
    }
}

#[test]
fn agent_state_repo_names_survive_the_real_git_namer() {
    // The corpus was generated with the production namer, which shells out to
    // `git remote get-url origin`. Every fixture path is non-existent, so both
    // languages take the basename branch — this pins that, so a future corpus
    // built inside a checkout would fail loudly instead of quietly encoding one
    // machine's remotes.
    let data = fixture("agent_state.json");
    let clock = Arc::new(ManualClock::new(1_000_000.0));
    let registry =
        AgentStateRegistry::with(clock, Arc::new(GitProjectNamer::new()), Arc::new(NoLabel));
    let case = data["sequences"]
        .as_array()
        .expect("array")
        .iter()
        .find(|c| as_str(&c["name"]) == "first_event_creates_agent_with_cwd_and_repo_name")
        .expect("the cwd case is in the corpus");
    for raw in case["events"].as_array().expect("events") {
        let event: AgentEvent = serde_json::from_value(raw.clone()).expect("event");
        registry.observe(&event);
    }
    assert_eq!(
        registry.get("s1").expect("agent").repo_name.as_deref(),
        Some("heard")
    );
}

