#[test]
fn session_scripts_match() {
    let data = fixture("session.json");
    let start = data["start_time"].as_f64().expect("start_time");
    for script in data["scripts"].as_array().expect("scripts") {
        let name = as_str(&script["name"]);
        let clock = Arc::new(ManualClock::new(start));
        let store = SessionStore::with_clock(clock.clone());
        let mut trace: Vec<Value> = Vec::new();
        for op in script["ops"].as_array().expect("ops") {
            match as_str(&op["op"]) {
                "advance" => clock.advance(op["seconds"].as_f64().expect("seconds")),
                "touch" => {
                    let view = store.touch(
                        as_str(&op["session_id"]),
                        op.get("cwd").and_then(Value::as_str),
                    );
                    trace.push(session_view_pairs(&view));
                }
                "get" => {
                    let view = store.get(as_str(&op["session_id"]));
                    trace.push(session_view_pairs(&view));
                }
                "note_failure" => store.note_failure(as_str(&op["session_id"])),
                "note_topic" => store.note_topic(as_str(&op["session_id"]), as_str(&op["topic"])),
                "record_tool_event" => store.record_tool_event(as_str(&op["session_id"])),
                "tool_density" => {
                    trace.push(Value::from(store.tool_density(as_str(&op["session_id"]))))
                }
                other => panic!("{name}: unknown session op {other:?}"),
            }
        }
        assert_eq!(
            Value::Array(trace),
            script["trace"],
            "session script {name}"
        );
    }
}

/// `SessionView` back into the ordered-pairs shape the corpus records, which is
/// the Python dict's own insertion order: repo_name, failure_count, last_topic,
/// last_seen. An unknown session is `{}` — an empty pair list.
fn session_view_pairs(view: &heard_state::session::SessionView) -> Value {
    let Some(last_seen) = view.last_seen else {
        return Value::Array(vec![]);
    };
    Value::Array(vec![
        Value::Array(vec![
            Value::from("repo_name"),
            match &view.repo_name {
                Some(name) => Value::from(name.clone()),
                None => Value::Null,
            },
        ]),
        Value::Array(vec![
            Value::from("failure_count"),
            Value::from(view.failure_count),
        ]),
        Value::Array(vec![
            Value::from("last_topic"),
            match &view.last_topic {
                Some(topic) => Value::from(topic.clone()),
                None => Value::Null,
            },
        ]),
        Value::Array(vec![Value::from("last_seen"), Value::from(last_seen)]),
    ])
}

