#[test]
fn multi_agent_scripts_match() {
    let data = fixture("multi_agent.json");
    for script in data["scripts"].as_array().expect("scripts") {
        let name = as_str(&script["name"]);
        let start = script["start_time"].as_f64().expect("start_time");
        let clock = Arc::new(ManualClock::new(start));
        let router = MultiAgentRouter::with(clock.clone(), Arc::new(BasenameProjectNamer));
        let mut trace: Vec<Value> = Vec::new();
        for op in script["ops"].as_array().expect("ops") {
            match as_str(&op["op"]) {
                "advance" => clock.advance(op["seconds"].as_f64().expect("seconds")),
                "note_event" => router.note_event(
                    as_str(&op["session_id"]),
                    op.get("cwd").and_then(Value::as_str).unwrap_or(""),
                    op.get("path_hint").and_then(Value::as_str),
                ),
                "set_last_event" => router.backdate_for_test(
                    as_str(&op["session_id"]),
                    clock.now() + op["relative_to_now"].as_f64().expect("relative"),
                ),
                "add_to_digest" => router.add_to_digest(
                    as_str(&op["session_id"]),
                    as_str(&op["kind"]),
                    as_str(&op["tag"]),
                    as_str(&op["neutral"]),
                    op.get("ctx").cloned().filter(|v| !v.is_null()),
                ),
                "classify" => {
                    let voices: Option<HashMap<String, String>> = op
                        .get("agent_voices")
                        .filter(|v| !v.is_null())
                        .map(|v| serde_json::from_value(v.clone()).expect("agent_voices"));
                    let decision = router.classify(
                        as_str(&op["kind"]),
                        as_str(&op["tag"]),
                        as_str(&op["session_id"]),
                        voices.as_ref(),
                        op.get("auto_voices")
                            .and_then(Value::as_bool)
                            .unwrap_or(false),
                    );
                    trace.push(serde_json::json!({
                        "action": decision.action.as_str(),
                        "label_prefix": decision.label_prefix,
                        "voice_override": decision.voice_override,
                    }));
                }
                "mode" => trace.push(Value::from(router.mode().as_str())),
                "pin" => trace.push(Value::from(router.pin(as_str(&op["session_id"])))),
                "unpin" => router.unpin(),
                "note_flush_spoken" => router.note_flush_spoken(as_str(&op["session_id"])),
                "collect_project_flushes" => {
                    let flushes = router.collect_project_flushes(
                        op.get("auto_voices")
                            .and_then(Value::as_bool)
                            .unwrap_or(true),
                        Some(clock.now()),
                    );
                    trace.push(Value::Array(flushes.iter().map(flush_json).collect()));
                }
                "force_flush_all" => {
                    let flushes = router.force_flush_all(
                        op.get("auto_voices")
                            .and_then(Value::as_bool)
                            .unwrap_or(true),
                        Some(clock.now()),
                    );
                    trace.push(Value::Array(flushes.iter().map(flush_json).collect()));
                }
                "collect_digest" => {
                    let drained = router.collect_digest();
                    trace.push(Value::Array(
                        drained
                            .iter()
                            .map(|(info, events)| {
                                serde_json::json!({
                                    "session_id": info.session_id,
                                    "events": events.iter().map(digest_json).collect::<Vec<_>>(),
                                })
                            })
                            .collect(),
                    ));
                }
                "format_digest" => trace.push(match router.format_digest(None) {
                    Some(text) => Value::from(text),
                    None => Value::Null,
                }),
                "drain_session_summary" => {
                    let summary = router.drain_session_summary(
                        as_str(&op["session_id"]),
                        op.get("include_label")
                            .and_then(Value::as_bool)
                            .unwrap_or(true),
                    );
                    trace.push(match summary {
                        Some(text) => Value::from(text),
                        None => Value::Null,
                    });
                }
                "pending_count" => trace.push(Value::from(router.pending_count())),
                "clear_pending" => trace.push(Value::from(router.clear_pending())),
                "list_active" => {
                    trace.push(serde_json::to_value(router.list_active()).expect("list_active"))
                }
                "session_info" => {
                    trace.push(match router.session_info(as_str(&op["session_id"])) {
                        None => Value::Null,
                        Some(info) => serde_json::json!({
                            "session_id": info.session_id,
                            "cwd": info.cwd,
                            "repo_name": info.repo_name,
                            "repo_confidence": info.repo_confidence,
                            "event_seq": info.event_seq,
                            "pending": info.pending_digest.len(),
                        }),
                    })
                }
                other => panic!("{name}: unknown multi_agent op {other:?}"),
            }
        }
        assert_eq!(
            Value::Array(trace),
            script["trace"],
            "multi_agent script {name}"
        );
    }
}

fn digest_json(event: &DigestEvent) -> Value {
    // The corpus records a digest event as ordered pairs, because it came out
    // of a Python dict whose key order is kind/tag/neutral/ctx/ts.
    Value::Array(vec![
        Value::Array(vec![Value::from("kind"), Value::from(event.kind.clone())]),
        Value::Array(vec![Value::from("tag"), Value::from(event.tag.clone())]),
        Value::Array(vec![
            Value::from("neutral"),
            Value::from(event.neutral.clone()),
        ]),
        Value::Array(vec![Value::from("ctx"), event.ctx.clone()]),
        Value::Array(vec![Value::from("ts"), Value::from(event.ts)]),
    ])
}

fn flush_json(flush: &heard_state::multi_agent::ProjectFlush) -> Value {
    serde_json::json!({
        "project_key": flush.project_key,
        "label": flush.label,
        "events": flush.events.iter().map(digest_json).collect::<Vec<_>>(),
        "member_session_ids": flush.member_session_ids,
        "speaker_session_id": flush.speaker_session_id,
        "voice_override": flush.voice_override,
        "is_primary": flush.is_primary,
    })
}

// ---------------------------------------------------------------------------
// project-root inference (filesystem-shaped)
// ---------------------------------------------------------------------------

/// Guard that points `HOME` somewhere disposable and puts it back.
///
/// The Python tests do `monkeypatch.setenv("HOME", …)` for the same reason: the
/// walk stops at home, and there is no way to exercise that rule without moving
/// home. These cases run in one `#[test]` each so the env change is not racing
/// another test in the same binary.
struct HomeGuard(Option<String>);

impl HomeGuard {
    fn set(path: &Path) -> Self {
        let previous = std::env::var("HOME").ok();
        std::env::set_var("HOME", path);
        Self(previous)
    }
}

impl Drop for HomeGuard {
    fn drop(&mut self) {
        match self.0.take() {
            Some(home) => std::env::set_var("HOME", home),
            None => std::env::remove_var("HOME"),
        }
    }
}

fn build_tree(root: &Path, dirs: &Value, files: &Value) {
    for dir in dirs.as_array().expect("dirs") {
        fs::create_dir_all(root.join(as_str(dir))).expect("mkdir");
    }
    for file in files.as_array().expect("files") {
        let path = root.join(as_str(file));
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).expect("mkdir");
        }
        fs::write(&path, "").expect("touch");
    }
}

