#[test]
fn find_project_root_matches() {
    let data = fixture("project_root.json");
    for case in data["find_project_root"].as_array().expect("array") {
        let name = as_str(&case["name"]);
        let root = scratch(&format!("root-{name}"));
        // Symlinked temp dirs (/var -> /private/var on macOS) would make the
        // recorded relative paths unresolvable, so canonicalise up front —
        // exactly what `_walk_stop_dirs` does for HOME and for the same reason.
        let root = fs::canonicalize(&root).expect("canonical scratch");
        build_tree(&root, &case["dirs"], &case["files"]);
        let _home = case["home"]
            .as_str()
            .map(|home| HomeGuard::set(&root.join(home)));
        for query in case["queries"].as_array().expect("queries") {
            let finder = ProjectRootFinder::new();
            let raw = as_str(&query["path"]);
            let target = if raw.is_empty() {
                String::new()
            } else {
                root.join(raw).to_string_lossy().into_owned()
            };
            let found = finder.find(&target);
            let relative = found.map(|f| {
                Path::new(&f)
                    .strip_prefix(&root)
                    .map(|p| p.to_string_lossy().into_owned())
                    .unwrap_or(f)
            });
            assert_eq!(
                relative,
                opt_string(&query["expect"]),
                "{name}: find_project_root({raw:?})"
            );
        }
        let _ = fs::remove_dir_all(&root);
    }
}

#[test]
fn repo_inference_tiers_match() {
    let data = fixture("project_root.json");
    let inference = &data["repo_inference"];
    let root = scratch("infer");
    let root = fs::canonicalize(&root).expect("canonical scratch");
    build_tree(&root, &inference["dirs"], &Value::Array(vec![]));

    for case in inference["cases"].as_array().expect("cases") {
        let name = as_str(&case["name"]);
        let _home = HomeGuard::set(&root.join(as_str(&case["home"])));
        let router = MultiAgentRouter::with(
            Arc::new(ManualClock::new(1_000.0)),
            Arc::new(BasenameProjectNamer),
        );
        let cwd = root
            .join(as_str(&case["cwd"]))
            .to_string_lossy()
            .into_owned();
        let hint = case["path_hint"]
            .as_str()
            .map(|h| root.join(h).to_string_lossy().into_owned());
        router.note_event("s1", &cwd, hint.as_deref());
        let info = router.session_info("s1").expect("session");
        assert_eq!(
            info.repo_name,
            as_str(&case["expect_repo_name"]),
            "{name}: repo_name"
        );
        assert_eq!(
            u64::from(info.repo_confidence),
            case["expect_confidence"].as_u64().expect("confidence"),
            "{name}: confidence"
        );
    }

    let ladder = &inference["upgrade_ladder"];
    let _home = HomeGuard::set(&root.join(as_str(&ladder["home"])));
    let router = MultiAgentRouter::with(
        Arc::new(ManualClock::new(1_000.0)),
        Arc::new(BasenameProjectNamer),
    );
    let weak = root
        .join(as_str(&ladder["weak_cwd"]))
        .to_string_lossy()
        .into_owned();
    let strong = root
        .join(as_str(&ladder["strong_hint"]))
        .to_string_lossy()
        .into_owned();
    let mut observed: Vec<Value> = Vec::new();
    let record = |router: &MultiAgentRouter, observed: &mut Vec<Value>| {
        let info = router.session_info("s1").expect("session");
        observed.push(Value::Array(vec![
            Value::from(info.repo_name),
            Value::from(info.repo_confidence),
        ]));
    };
    router.note_event("s1", &weak, None);
    record(&router, &mut observed);
    router.note_event("s1", &weak, Some(&strong));
    record(&router, &mut observed);
    router.note_event("s1", &weak, None);
    record(&router, &mut observed);
    assert_eq!(Value::Array(observed), ladder["expect"]);

    let _ = fs::remove_dir_all(&root);
}

